event: response.output_text.done
data: {"type":"response.output_text.done","content_index":0,"item_id":"msg_0ec0256549524424016aecbe456a2887d291ac55bc2917b54f","logprobs":[],"output_index":0,"sequence_number":537,"text":"<title>Café order</title>\n<meta name=\"idea\" content=\"Browse a compact café menu and start a customizable order\">\n<meta name=\"spec\" content=\"data.prices = Menu prices are in USD\">\n\n<header>\n  <h1>Daybreak Café</h1>\n  <p><small>Fresh coffee, made to order</small></p>\n  <nav aria-label=\"Main navigation\">\n    <a href=\"#menu\">Menu</a> ·\n    <button data-action=\"@orders: Recent café orders and reorder options\">Orders</button> ·\n    <button data-action=\"@profile: Café account profile and saved preferences\">Profile</button>\n  </nav>\n</header>\n<main id=\"menu\">\n  <h2>Popular today</h2>\n  <article>\n    <h3>Vanilla latte <small>$4.75</small></h3>\n    <p>Espresso, steamed milk, house vanilla.</p>\n    <button data-action=\"@vanilla-latte: Details and customization for a vanilla latte at Daybreak Café\">Customize</button>\n  </article>\n  <article>\n    <h3>Cold brew <small>$4.25</small></h3>\n    <p>Slow-steeped for a smooth, refreshing finish.</p>\n    <button data-action=\"@cold-brew: Details and customization for a cold brew at Daybreak Café\">Customize</button>\n  </article>\n  <article>\n    <h3>Butter croissant <small>$3.50</small></h3>\n    <p>Flaky, golden, baked fresh this morning.</p>\n    <button data-action=\"@croissant: Details and customization for a butter croissant at Daybreak Café\">Customize</button>\n  </article>\n  <article>\n    <h3>Order summary</h3>\n    <label for=\"quantity\">Vanilla lattes</label>\n    <input id=\"quantity\" type=\"number\" min=\"0\" value=\"1\">\n    <p>Subtotal <strong id=\"subtotal\">$4.75</strong></p>\n    <button data-action=\"@order-checkout: Checkout for a Daybreak Café order with vanilla lattes\">Go to checkout</button>\n  </article>\n</main>\n<script>\nconst quantity = document.querySelector(\"#quantity\");\nconst subtotal = document.querySelector(\"#subtotal\");\nquantity.addEventListener(\"input\", () => {\n  subtotal.textContent = \"$\" + ((Number(quantity.value) || 0) * 4.75).toFixed(2);\n});\n</script>"}

